//! Tests against the shared reference files in `tests/test-files`.
//!
//! - every JSON file must decode and then re-encode to exactly the same bytes
//! - schemas generated by `#[derive(ArriModel)]` must match the definitions in `AppDefinition.json`
#![deny(warnings)]
#![allow(deprecated)]

use std::{collections::BTreeMap, path::PathBuf};

use arri::{ArriModel, ArriSchema, Nullable, Timestamp, Value, json, to_value, type_def_of};

/// This is a book
#[derive(ArriModel, Debug, PartialEq)]
#[arri(rename_all = "camelCase")]
struct Book {
    /// The book ID
    id: String,
    /// The book title
    name: String,
    /// When the book was created
    #[deprecated]
    created_at: Timestamp,
    #[deprecated]
    updated_at: Timestamp,
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(rename_all = "camelCase")]
struct BookParams {
    book_id: String,
}

#[derive(ArriModel, Debug, PartialEq)]
struct NestedObject {
    id: String,
    content: String,
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(rename_all = "SCREAMING_SNAKE_CASE")]
enum Enumerator {
    Foo,
    Bar,
    Baz,
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(rename_all = "kebab-case")]
enum UnionExternal {
    Object(NestedObject),
    Array(Vec<String>),
    Boolean(bool),
    NullableTimestamp(Nullable<Timestamp>),
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(tag_key = "shape", rename_all = "lowercase")]
enum UnionInternal {
    Rectangle { width: f64, height: f64 },
    Circle { radius: f64 },
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(tag_key = "kind", value_key = "data", rename_all = "kebab-case")]
enum UnionAdjacent {
    Object(NestedObject),
    Array(Vec<String>),
    Boolean(bool),
    NullableTimestamp(Nullable<Timestamp>),
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(rename_all = "camelCase")]
struct ObjectWithEveryType {
    string: String,
    boolean: bool,
    timestamp: Timestamp,
    float32: f32,
    float64: f64,
    int8: i8,
    uint8: u8,
    int16: i16,
    uint16: u16,
    int32: i32,
    uint32: u32,
    int64: i64,
    uint64: u64,
    r#enum: Enumerator,
    object: NestedObject,
    array: Vec<bool>,
    record: BTreeMap<String, bool>,
    union_external: UnionExternal,
    union_internal: UnionInternal,
    union_adjacent: UnionAdjacent,
    any: Value,
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(rename_all = "camelCase")]
struct ObjectWithOptionalFields {
    string: Option<String>,
    boolean: Option<bool>,
    timestamp: Option<Timestamp>,
    float32: Option<f32>,
    float64: Option<f64>,
    int8: Option<i8>,
    uint8: Option<u8>,
    int16: Option<i16>,
    uint16: Option<u16>,
    int32: Option<i32>,
    uint32: Option<u32>,
    int64: Option<i64>,
    uint64: Option<u64>,
    r#enum: Option<Enumerator>,
    object: Option<NestedObject>,
    array: Option<Vec<bool>>,
    record: Option<BTreeMap<String, bool>>,
    union_external: Option<UnionExternal>,
    union_internal: Option<UnionInternal>,
    union_adjacent: Option<UnionAdjacent>,
    any: Option<Value>,
}

#[derive(ArriModel, Debug, PartialEq)]
#[arri(rename_all = "camelCase")]
struct ObjectWithNullableFields {
    string: Nullable<String>,
    boolean: Nullable<bool>,
    timestamp: Nullable<Timestamp>,
    float32: Nullable<f32>,
    float64: Nullable<f64>,
    int8: Nullable<i8>,
    uint8: Nullable<u8>,
    int16: Nullable<i16>,
    uint16: Nullable<u16>,
    int32: Nullable<i32>,
    uint32: Nullable<u32>,
    int64: Nullable<i64>,
    uint64: Nullable<u64>,
    r#enum: Nullable<Enumerator>,
    object: Nullable<NestedObject>,
    array: Nullable<Vec<bool>>,
    record: Nullable<BTreeMap<String, bool>>,
    union_external: Nullable<UnionExternal>,
    union_internal: Nullable<UnionInternal>,
    union_adjacent: Nullable<UnionAdjacent>,
    any: Nullable<Value>,
}

#[derive(ArriModel, Debug, PartialEq)]
struct RecursiveObject {
    left: Nullable<Box<RecursiveObject>>,
    right: Nullable<Box<RecursiveObject>>,
}

#[derive(ArriModel, Debug, PartialEq)]
struct EmptyObject {}

fn test_file(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../tests/test-files")
        .join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()))
        .trim_end()
        .to_string()
}

/// Decode the file, re-encode it, and make sure the output is identical to the input
fn assert_round_trip<T: ArriModel + std::fmt::Debug + PartialEq>(file: &str) -> T {
    let input = test_file(file);
    let decoded: T = json::from_str(&input).unwrap_or_else(|e| panic!("{file}: {e}"));
    let encoded = json::to_string(&decoded).unwrap();
    assert_eq!(encoded, input, "{file} did not round trip");
    // decoding the output again should produce an equal value
    assert_eq!(json::from_str::<T>(&encoded).unwrap(), decoded);
    decoded
}

#[test]
fn round_trip_test_files() {
    assert_round_trip::<Book>("Book.json");
    assert_round_trip::<BookParams>("BookParams.json");
    assert_round_trip::<EmptyObject>("EmptyObject.json");
    assert_round_trip::<NestedObject>("NestedObject_NoSpecialChars.json");
    assert_round_trip::<NestedObject>("NestedObject_SpecialChars.json");
    assert_round_trip::<ObjectWithEveryType>("ObjectWithEveryType.json");
    assert_round_trip::<ObjectWithNullableFields>("ObjectWithNullableFields_AllNull.json");
    assert_round_trip::<ObjectWithNullableFields>("ObjectWithNullableFields_NoNull.json");
    assert_round_trip::<ObjectWithOptionalFields>("ObjectWithOptionalFields_AllUndefined.json");
    assert_round_trip::<ObjectWithOptionalFields>("ObjectWithOptionalFields_NoUndefined.json");
    assert_round_trip::<RecursiveObject>("RecursiveObject.json");
    assert_round_trip::<UnionExternal>("UnionExternal_Object.json");
    assert_round_trip::<UnionExternal>("UnionExternal_Array.json");
    assert_round_trip::<UnionExternal>("UnionExternal_Boolean.json");
    assert_round_trip::<UnionExternal>("UnionExternal_Timestamp.json");
    assert_round_trip::<UnionExternal>("UnionExternal_TimestampNull.json");
    assert_round_trip::<UnionInternal>("UnionInternal_Rectangle.json");
    assert_round_trip::<UnionAdjacent>("UnionAdjacent_Object.json");
    assert_round_trip::<UnionAdjacent>("UnionAdjacent_TimestampNull.json");
}

#[test]
fn decoded_values_are_correct() {
    let every_type: ObjectWithEveryType = assert_round_trip("ObjectWithEveryType.json");
    assert_eq!(every_type.int64, 1000);
    assert_eq!(every_type.uint64, 1000);
    assert_eq!(every_type.r#enum, Enumerator::Baz);
    assert_eq!(
        every_type.timestamp,
        Timestamp::parse("2001-01-01T16:00:00Z").unwrap()
    );
    assert_eq!(
        every_type.union_external,
        UnionExternal::Array(vec!["hello".into(), "world".into()])
    );
    assert_eq!(
        every_type.union_internal,
        UnionInternal::Circle { radius: 2.5 }
    );
    assert_eq!(every_type.any, Value::from("hello world"));

    let special: NestedObject = assert_round_trip("NestedObject_SpecialChars.json");
    assert_eq!(
        special.content,
        "double-quote: \" | backslash: \\ | backspace: \u{8} | form-feed: \u{c} | newline: \n | carriage-return: \r | tab: \t | unicode: \u{0}"
    );

    let optional: ObjectWithOptionalFields =
        assert_round_trip("ObjectWithOptionalFields_AllUndefined.json");
    assert_eq!(optional.string, None);
    assert_eq!(optional.any, None);

    let recursive: RecursiveObject = assert_round_trip("RecursiveObject.json");
    let Nullable::Present(left) = recursive.left else {
        panic!("expected left to be present")
    };
    assert!(left.right.is_null());
}

/// Recursively sort object keys and remove empty `metadata` objects so that schemas can be compared
fn normalize(value: Value) -> Value {
    match value {
        Value::Object(entries) => {
            let mut entries: Vec<(String, Value)> = entries
                .into_iter()
                .filter(|(k, v)| !(k == "metadata" && v.as_object().is_some_and(|o| o.is_empty())))
                .map(|(k, v)| (k, normalize(v)))
                .collect();
            entries.sort_by(|a, b| a.0.cmp(&b.0));
            Value::Object(entries)
        }
        Value::List(items) => Value::List(items.into_iter().map(normalize).collect()),
        other => other,
    }
}

fn assert_schema_matches<T: ArriSchema>(name: &str) {
    let app_def: Value = json::from_str(&test_file("AppDefinition.json")).unwrap();
    let expected = app_def
        .get("definitions")
        .and_then(|d| d.get(name))
        .unwrap_or_else(|| panic!("AppDefinition.json is missing {name}"))
        .clone();
    let actual = to_value(&type_def_of::<T>()).unwrap();
    assert_eq!(
        json::to_string(&normalize(actual)).unwrap(),
        json::to_string(&normalize(expected)).unwrap(),
        "schema for {name} does not match AppDefinition.json"
    );
}

#[test]
fn schemas_match_app_definition() {
    assert_schema_matches::<Book>("Book");
    assert_schema_matches::<BookParams>("BookParams");
    assert_schema_matches::<NestedObject>("NestedObject");
    assert_schema_matches::<ObjectWithEveryType>("ObjectWithEveryType");
    assert_schema_matches::<ObjectWithOptionalFields>("ObjectWithOptionalFields");
    assert_schema_matches::<ObjectWithNullableFields>("ObjectWithNullableFields");
    assert_schema_matches::<UnionExternal>("UnionExternal");
    assert_schema_matches::<UnionInternal>("UnionInternal");
    assert_schema_matches::<UnionAdjacent>("UnionAdjacent");
    assert_schema_matches::<RecursiveObject>("RecursiveObject");
}

#[test]
fn empty_object_schema() {
    // the reference EmptyObject has no id so it's compared separately
    assert_eq!(
        type_def_of::<EmptyObject>().to_json(),
        r#"{"properties":{},"metadata":{"id":"EmptyObject"}}"#
    );
}

/// Decoding malformed input must return an error rather than panic.
///
/// Every prefix of every test file is decoded, along with a few thousand random byte mutations.
#[test]
fn malformed_input_never_panics() {
    fn decode_all(input: &[u8]) {
        let _ = json::from_slice::<Value>(input);
        let _ = json::from_slice::<ObjectWithEveryType>(input);
        let _ = json::from_slice::<ObjectWithNullableFields>(input);
        let _ = json::from_slice::<ObjectWithOptionalFields>(input);
        let _ = json::from_slice::<RecursiveObject>(input);
        let _ = json::from_slice::<UnionExternal>(input);
        let _ = json::from_slice::<UnionInternal>(input);
        let _ = json::from_slice::<UnionAdjacent>(input);
        let _ = json::from_slice::<NestedObject>(input);
    }

    // small deterministic xorshift PRNG so that failures are reproducible
    let mut state: u64 = 0x9E37_79B9_7F4A_7C15;
    let mut next = move || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    const INTERESTING: &[u8] = b"{}[]\":,\\-0123456789.eEnulltruefalse \x00\xff\xc3";

    let files = [
        "ObjectWithEveryType.json",
        "ObjectWithNullableFields_AllNull.json",
        "ObjectWithNullableFields_NoNull.json",
        "ObjectWithOptionalFields_NoUndefined.json",
        "RecursiveObject.json",
        "NestedObject_SpecialChars.json",
        "UnionExternal_TimestampNull.json",
        "UnionInternal_Rectangle.json",
        "UnionAdjacent_Object.json",
    ];
    for file in files {
        let input = test_file(file).into_bytes();
        for len in 0..input.len() {
            decode_all(&input[..len]);
        }
        for _ in 0..500 {
            let mut mutated = input.clone();
            for _ in 0..(next() % 4 + 1) {
                let index = (next() as usize) % mutated.len();
                let byte = INTERESTING[(next() as usize) % INTERESTING.len()];
                match next() % 3 {
                    0 => mutated[index] = byte,
                    1 => mutated.insert(index, byte),
                    _ => {
                        mutated.remove(index);
                    }
                }
                if mutated.is_empty() {
                    break;
                }
            }
            decode_all(&mutated);
        }
    }
}

#[test]
fn definitions_match_app_definition() {
    let app_def: Value = json::from_str(&test_file("AppDefinition.json")).unwrap();
    let mut ctx = arri::SchemaContext::new();
    ObjectWithEveryType::type_def(&mut ctx);
    ObjectWithNullableFields::type_def(&mut ctx);
    RecursiveObject::type_def(&mut ctx);
    let definitions = ctx.into_definitions().unwrap();
    let ids: Vec<&str> = definitions.iter().map(|(id, _)| id.as_str()).collect();
    assert_eq!(
        ids,
        [
            "ObjectWithEveryType",
            "Enumerator",
            "NestedObject",
            "UnionExternal",
            "UnionInternal",
            "UnionAdjacent",
            "ObjectWithNullableFields",
            "RecursiveObject",
        ]
    );
    for (id, def) in definitions {
        // Enumerator isn't listed in the reference definitions
        let Some(expected) = app_def.get("definitions").and_then(|d| d.get(&id)) else {
            assert_eq!(id, "Enumerator");
            continue;
        };
        assert_eq!(
            json::to_string(&normalize(to_value(&def).unwrap())).unwrap(),
            json::to_string(&normalize(expected.clone())).unwrap(),
            "definition for {id} does not match AppDefinition.json"
        );
    }
}
